steps.instructions:
Write a fully remediated `main_secure.tf` that addresses every finding.

```hcl
# ~/lab09b/main_secure.tf — HARDENED VERSION
provider "aws" {
  region = "eu-west-1"
}

# FIXED: Restrict SSH to VPN CIDR only; remove public DB access
resource "aws_security_group" "web_sg" {
  name        = "web-server-sg-secure"
  description = "Web server security group"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]  # Only internal/VPN
    description = "SSH from internal network only"
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
    description = "HTTPS from anywhere"
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    description = "Allow all outbound"
  }
}

# FIXED: S3 bucket with all security controls
resource "aws_s3_bucket" "data" {
  bucket = "company-data-secure-12345"
}

resource "aws_s3_bucket_public_access_block" "data" {
  bucket                  = aws_s3_bucket.data.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data" {
  bucket = aws_s3_bucket.data.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "data" {
  bucket = aws_s3_bucket.data.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_logging" "data" {
  bucket        = aws_s3_bucket.data.id
  target_bucket = aws_s3_bucket.data.id  # Use separate log bucket in real use
  target_prefix = "access-logs/"
}

# FIXED: CloudTrail with integrity validation + multi-region
resource "aws_cloudtrail" "main" {
  name                          = "main-trail-secure"
  s3_bucket_name                = aws_s3_bucket.data.id
  enable_logging                = true
  enable_log_file_validation    = true  # Integrity validation
  is_multi_region_trail         = true  # All regions
  include_global_service_events = true
}
```
